export function toFlowNodes(layer, onDelete) { return layer.nodes.map(node => ({ id: node.id, type: 'recipe', position: { x: node.x, y: node.y }, data: { node, onDelete: () => onDelete(node.id) } })); }
export function toFlowEdges(layer) { return [...layer.connections.map(edge => ({ id: `${edge.from}-${edge.to}-${edge.toPort || 'input'}`, source: edge.from, target: edge.to, sourceHandle: 'output', targetHandle: edge.toPort || 'input', type: 'smoothstep' })), ...layer.parameterConnections.map(edge => ({ id: `${edge.fromNode}-${edge.toNode}-${edge.toParam}`, source: edge.fromNode, target: edge.toNode, sourceHandle: 'output', targetHandle: `param:${edge.toParam}`, type: 'smoothstep', className: 'rf-parameter-edge' }))]; }
